'use strict';
// Synthetic observations for interaction design. Million KRW; no live data or model calls.
const months=Array.from({length:24},(_,i)=>{const d=new Date(Date.UTC(2024,10+i,1));return `${d.getUTCFullYear()}.${String(d.getUTCMonth()+1).padStart(2,'0')}`;});
const universe=[
 {id:'A',name:'서울숲 아뜰리에',region:'성수 생활권',area:59,py:25,year:2012,units:620,structure:'계단식 · 방 3',base:1490,growth:5.6,phase:0,lease:760,ads:16,prevAds:20,weekAds:18,turn:7,asking:1640,prevAsk:1660,weekAsk:1650,focus:'호가는 내리는데 거래는 늘까?'},
 {id:'B',name:'잠원 리버테라스',region:'잠원 생활권',area:84,py:33,year:2005,units:920,structure:'계단식 · 방 3',base:1710,growth:3.7,phase:2,lease:910,ads:31,prevAds:24,weekAds:28,turn:5,asking:1880,prevAsk:1890,weekAsk:1880,focus:'전세와 매매 흐름이 왜 달라질까?'},
 {id:'C',name:'마포 파크센트럴',region:'마포 생활권',area:84,py:34,year:2014,units:1180,structure:'계단식 · 방 3',base:1820,growth:4.8,phase:4,lease:1020,ads:19,prevAds:17,weekAds:18,turn:9,asking:2000,prevAsk:1960,weekAsk:1980,focus:'비교 단지와 가격차가 벌어지는가?'},
 {id:'D',name:'반포 그로브',region:'반포 생활권',area:84,py:34,year:2009,units:460,structure:'계단식 · 방 3',base:2070,growth:6.2,phase:1,lease:1080,ads:12,prevAds:12,weekAds:11,turn:2,asking:2310,prevAsk:2270,weekAsk:2290,focus:'적은 거래로 보이는 추세는 믿을 만한가?'},
 {id:'E',name:'대치 가든코트',region:'대치 생활권',area:84,py:33,year:1998,units:760,structure:'계단식 · 방 3',base:2250,growth:5,phase:3,lease:1120,ads:26,prevAds:21,weekAds:24,turn:3,asking:2500,prevAsk:2500,weekAsk:2500,focus:'정비사업 변화가 실제 단계 전진인가?'},
 {id:'F',name:'잠실 레이크하우스',region:'잠실 생활권',area:84,py:34,year:2008,units:1420,structure:'계단식 · 방 3',base:2360,growth:4.2,phase:5,lease:1260,ads:null,prevAds:null,weekAds:null,turn:6,asking:null,prevAsk:null,weekAsk:null,focus:'호가가 없는 출처에서 무엇까지 읽을 수 있나?'}
];
for(const c of universe){
 c.sale=months.map((_,i)=>Math.round(c.base+i*c.growth+Math.sin((i+c.phase)/3)*28+(i>18?(i-18)*(c.id==='A'?-12:c.id==='C'?9:2):0)));
 c.rent=months.map((_,i)=>Math.round(c.lease+i*(c.id==='B'?7:3)+Math.cos((i+c.phase)/4)*12));
 c.rows=months.flatMap((month,i)=>{
   let n=Math.max(1,c.turn+((i+c.phase)%5)-2);if(c.id==='D'&&i===23)n=1;if(c.id==='E'&&i===23)n=0;
   return Array.from({length:n},(_,j)=>{const floor=[3,9,15,22,12,5,18,25,8,14,20][(j+i+c.phase)%11];return {id:`${c.id}-${i}-${j}`,i,month,date:`${month}.${String(3+j*2).padStart(2,'0')}`,observed:`${month}.${String(Math.min(28,12+j*2)).padStart(2,'0')}`,price:c.sale[i]+(floor<6?-65:floor>20?45:0)+(j-(n-1)/2)*6,floor,area:c.area,cancelled:j===0&&i%7===0,type:j%7===6?'직거래':'중개거래'};});
 });
}
const state={view:'market',watchDistrict:'all',selected:'B',metric:'sale',period:12,month:23,floor:'all',minSamples:0,sort:'name',mode:'factors',compare:['B','C','E'],benchmark:'B',compareMetric:'sale',invKind:'both',invPeriod:30,invScale:'count',invDay:90,invDistrict:'서울 전체',chart:'indexed',radar:'all',case:'lease',frequency:'month',asof:'published',tasks:{},notes:'',researchTab:'services'};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null?'미확인':Math.abs(n)>=100?`${(n/100).toFixed(2).replace(/0+$/,'').replace(/\.$/,'')}억`:`${Math.round(n*100).toLocaleString('ko-KR')}만`;
const pct=n=>n==null?'—':`${n>0?'+':''}${n.toFixed(1)}%`;
const signed=n=>n==null?'—':`${n>0?'+':n<0?'−':''}${money(Math.abs(n))}`;
const median=a=>{if(!a.length)return null;const b=[...a].sort((x,y)=>x-y),i=Math.floor(b.length/2);return b.length%2?b[i]:(b[i-1]+b[i])/2;};
const average=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
const change=(a,b)=>a==null||b==null||b===0?null:(a/b-1)*100;
const current=()=>universe.find(c=>c.id===state.selected);
const observedRows=(c,start=0,end=23,floor=state.floor)=>c.rows.filter(r=>!r.cancelled&&r.i>=start&&r.i<=end&&(floor==='all'||r.floor>=6&&r.floor<=20));
const sampleStats=(c,m=state.month)=>{const recent=observedRows(c,Math.max(0,m-2),m),prev=observedRows(c,Math.max(0,m-5),Math.max(0,m-3));const v=median(recent.map(r=>r.price)),old=median(prev.map(r=>r.price));return {value:v,n:recent.length,monthN:observedRows(c,m,m).length,momentum:change(v,old),askGap:c.asking==null?null:change(c.asking,v),inventory:change(c.ads,c.prevAds),leaseRatio:c.rent[m]/c.sale[m]*100};};
const metricValue=(c,i,key=state.metric)=>key==='sale'?c.sale[i]:key==='rent'?c.rent[i]:key==='ratio'?c.rent[i]/c.sale[i]*100:key==='gap'?c.sale[i]-c.rent[i]:c.sale[i]/c.py;
const metricName={sale:'매매 관찰가',rent:'전세 관찰가',ratio:'전세가율',gap:'매전갭',per:'공급 평당가'};
const metricFormat=(n,key=state.metric)=>n==null?'—':key==='ratio'?`${n.toFixed(1)}%`:money(n);
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',grid:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18M15 3v18"/>',book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2ZM12 5v16"/>',layers:'<path d="m3 7 9-4 9 4-9 4ZM3 12l9 4 9-4M3 17l9 4 9-4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'}[name]||'<path d="M5 12h14m-6-6 6 6-6 6"/>')}</svg>`;
const pill=(text,type='')=>`<span class="pill ${type}">${text}</span>`;
function header(active){return `<header class="site-header"><div class="site-wordmark">${icon('grid')}둘이서은퇴 <em>PROPERTY RESEARCH</em></div><div class="header-links"><span class="optional">관심 단지 6</span><span class="current">${active}</span><button class="btn text" data-action="dictionary">지표 사전 ${icon('book')}</button></div></header>`}
function caption(n,title,desc){return `<footer class="concept-caption"><span><b>${n} ${title}</b> · ${desc}</span><span>지속적인 관찰 → 근거 축적 → 나의 가격 판단</span></footer>`}
function candidatesNav(){return `<div class="candidate-pills" aria-label="분석할 단지">${universe.map(c=>`<button data-select="${c.id}" aria-pressed="${c.id===state.selected}"><span>${c.id}</span>${c.name}<small>${c.area}㎡</small></button>`).join('')}</div>`}
function spark(values,color='#8ed2c8'){const good=values.filter(x=>x!=null);if(!good.length)return '—';const lo=Math.min(...good)-1,hi=Math.max(...good)+1;return `<svg class="spark" viewBox="0 0 92 32" aria-hidden="true"><polyline points="${values.map((v,i)=>v==null?'':`${3+i/(values.length-1)*86},${28-(v-lo)/(hi-lo)*24}`).filter(Boolean).join(' ')}" stroke="${color}" stroke-width="1.6" fill="none"/></svg>`}
function lineChart(series,{unit='',indexed=false,height=250}={}){const colors=['#0f5c4a','#1b64da','#d397b5','#8b95a1'];const valid=series.flatMap(s=>s.values.filter(v=>v!=null));if(!valid.length)return '<p class="note">비교할 자료가 없습니다.</p>';let lo=Math.min(...valid),hi=Math.max(...valid);const span=hi-lo||1;lo-=span*.15;hi+=span*.15;const left=58,right=680,top=20,bottom=height-40;let svg=`<svg class="research-chart" viewBox="0 0 720 ${height}" role="img" aria-label="${series.map(s=>s.name).join(' 및 ')} ${indexed?'시작월을 100으로 바꾼':'관측값'} 추이"><rect x="${left}" y="${top}" width="${right-left}" height="${bottom-top}" fill="none"/>`;for(let i=0;i<4;i++){const val=lo+(hi-lo)*i/3,y=bottom-(val-lo)/(hi-lo)*(bottom-top);svg+=`<path d="M${left} ${y}H${right}" stroke="#e5e8eb"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#6b7684" font-size="12">${indexed?val.toFixed(0):unit==='%'?val.toFixed(1):money(val)}</text>`;}series.forEach((s,k)=>{let path='';let drawing=false;s.values.forEach((v,i)=>{if(v==null){drawing=false;return}const x=left+i/(s.values.length-1)*(right-left),y=bottom-(v-lo)/(hi-lo)*(bottom-top);path+=`${drawing?'L':'M'}${x},${y} `;drawing=true;});svg+=`<path d="${path}" fill="none" stroke="${s.color||colors[k%colors.length]}" stroke-width="2.5"/>`;});const n=series[0].values.length,labels=[0,Math.floor((n-1)/2),n-1];labels.forEach(i=>{svg+=`<text x="${left+i/(n-1)*(right-left)}" y="${height-10}" text-anchor="middle" fill="#6b7684" font-size="12">${months[24-n+i]}</text>`});svg+='</svg>';return `${svg}<div class="chart-legend">${series.map((s,k)=>`<span><i style="background:${s.color||colors[k%colors.length]}"></i>${s.name}</span>`).join('')}</div>`}
function workbook(){const scope=visibleComplexes(),c=scope.find(x=>x.id===state.selected)||scope[0]||current(),stats=sampleStats(c);let list=visibleComplexes(universe.filter(x=>sampleStats(x).n>=state.minSamples));if(state.sort==='spread')list.sort((a,b)=>(sampleStats(b).askGap??-Infinity)-(sampleStats(a).askGap??-Infinity));if(state.sort==='inventory')list.sort((a,b)=>(sampleStats(b).inventory??-Infinity)-(sampleStats(a).inventory??-Infinity));const adsChange=scope.some(x=>x.ads!=null)?scope.filter(x=>x.ads!=null).reduce((n,x)=>n+x.ads-x.prevAds,0):null;return `${header('시장 · 관심 단지')}<div class="page">${marketTabs()}${watchDistrictNav()}<section class="intro"><div><div class="eyebrow">01 / A personal property terminal</div><h1>관심 단지</h1><p>자치구별 가격 · 전세 · 거래 · 매물의 흐름.</p></div><div class="terminal-stamp"><span class="dot"></span> SYNTHETIC DATASET<br><b>2026.11.07</b><small>가격 관측 24개월 · 실제 시장 아님</small></div></section><div class="quant-summary"><div><span>${state.watchDistrict==='all'?'전체 관심 지역':state.watchDistrict}</span><strong>${String(scope.length).padStart(2,'0')}<small>단지</small></strong><p>단지 + 전용면적 단위</p></div><div><span>관측 광고 변화</span><strong>${adsChange==null?'—':`${adsChange>0?'+':''}${adsChange}`}<small>건</small></strong><p>10.01 → 11.01 · 동일 예시 출처</p></div><div><span>최근 3개월 거래 표본</span><strong>${scope.reduce((n,x)=>n+sampleStats(x).n,0)}<small>건</small></strong><p>선택 층 조건 · 해제 제외</p></div><div><span>현재 호가 미확인</span><strong>${String(scope.filter(x=>x.asking==null).length).padStart(2,'0')}<small>단지</small></strong><p>미확인은 0으로 채우지 않음</p></div></div><div class="panel-head quant-toolbar"><div class="tabs"><button data-mode="factors" aria-pressed="${state.mode==='factors'}">팩터 관측표</button><button data-mode="history" aria-pressed="${state.mode==='history'}">월별 추적표</button></div><div class="row wrap"><label>표본 <select id="sample-filter"><option value="0" ${state.minSamples===0?'selected':''}>전체</option><option value="10" ${state.minSamples===10?'selected':''}>3개월 10건 이상</option></select></label><label>구 안에서 정렬 <select id="factor-sort"><option value="name" ${state.sort==='name'?'selected':''}>관심 순서</option><option value="spread" ${state.sort==='spread'?'selected':''}>호가 괴리</option><option value="inventory" ${state.sort==='inventory'?'selected':''}>광고 증감</option></select></label></div></div>${comparisonTray()}${state.mode==='factors'?`<div class="quant-table-wrap"><table class="watch-table quant-table"><thead><tr><th>자치구 / 단지 / 평형</th><th>3개월 거래 중위값</th><th>이전 3개월 대비</th><th>현재 관찰 호가</th><th>호가 괴리</th><th>전세가율</th><th>관측 광고 변화</th><th>10월 거래</th><th>24개월 호가</th></tr></thead><tbody>${districtGroups(list).map(g=>workbookGroupRow(g,9,'factor')+g.items.map(x=>{const s=sampleStats(x);return `<tr data-complex="${x.id}" class="${x.id===state.selected?'selected':''}"><td><div class="workbook-name">${compareInput(x,'factor')}<button class="name-button" data-select="${x.id}">${x.name}<small>${x.area}㎡ · ${x.year}년 · ${x.units}세대</small></button></div></td><td><button data-evidence="${x.id}" data-kind="trades">${money(s.value)}<small>n=${s.n} · 8~10월</small></button></td><td class="${s.momentum>=0?'market-up':'market-down'}">${pct(s.momentum)}<small>표본 구성 변화 포함</small></td><td><button data-evidence="${x.id}" data-kind="listings">${money(x.asking)}<small>${x.asking?'11.01 관찰':'출처 미확인'}</small></button></td><td>${pct(s.askGap)}<small>호가 / 거래 − 1</small></td><td>${s.leaseRatio.toFixed(1)}%<small>전세 / 매매 관찰가</small></td><td>${pct(s.inventory)}<small>${x.ads==null?'수집 미확인':`${x.prevAds} → ${x.ads}건`}</small></td><td>${s.monthN}<small>선택 조건 표본</small></td><td>${spark(x.sale)}</td></tr>`}).join('')).join('')}${!list.length?'<tr><td colspan="9" class="workbook-empty">이 구에서 현재 표본 조건에 맞는 관심 단지가 없습니다.</td></tr>':''}</tbody></table></div>`:historyGrid(list)}<div class="quant-bottom"><section class="obs-brief"><div><span class="eyebrow">SELECTED RESEARCH QUESTION</span><h3 style="margin:12px 0">${c.name}</h3><p class="research-question">${c.focus}</p></div><div><div class="coverage-row"><span>최근 3개월 거래 중위값</span><b>${money(stats.value)}</b></div><div class="coverage-row" style="margin-top:14px"><span>현재 호가와의 차이</span><b>${pct(stats.askGap)}</b></div></div><div class="obs-source"><button class="btn" data-open="relative">선택한 단지 함께 비교 ${icon('arrow')}</button></div></section><section class="card"><div class="panel-head"><h2>이번 주 새 관측</h2><button class="btn text" data-view="journal">리포트로 보기 ↗</button></div><div class="event-row"><time>11.07</time><button data-evidence="B" data-kind="listings">리버테라스 · 관측 광고가 늘었지만 중복 여부는?</button>${pill('매물','gray')}</div><div class="event-row"><time>11.05</time><button data-evidence="A" data-kind="trades">과거 계약 1건이 뒤늦게 들어온 사례</button>${pill('정정','gray')}</div><div class="event-row"><time>11.04</time><button data-case="permit">정비사업 발표와 실제 인허가 단계 대조</button>${pill('공공 근거','gray')}</div><p class="note">예시 사건입니다. 가격의 좋고 나쁨은 판단하지 않고 변화와 근거를 모읍니다.</p></section></div>${researchInline(c)}</div>${caption('01','관심 단지 워크북','스크린샷의 월별 시세 추적표를 다변량 관측판으로')}`;}
function historyGrid(list){return `<section class="history-panel"><div class="row between wrap" style="margin:14px 0"><div class="tabs">${Object.entries(metricName).map(([key,label])=>`<button data-metric="${key}" aria-pressed="${state.metric===key}">${label}</button>`).join('')}</div><span class="note">매월 같은 관찰 기준 · 공급 평당 / 전용㎡ 구분</span></div><div class="quant-table-wrap"><table class="watch-table history-table"><thead><tr><th>자치구 / 단지 / 면적</th>${months.slice(-8).map(m=>`<th>${m}</th>`).join('')}<th>전월 변화</th></tr></thead><tbody>${districtGroups(list).map(g=>workbookGroupRow(g,10,'history')+g.items.map(c=>`<tr data-complex="${c.id}"><td><div class="workbook-name">${compareInput(c,'history')}<button class="name-button" data-select="${c.id}">${c.name}<small>${c.py}평형 · 전용 ${c.area}㎡</small></button></div></td>${months.slice(-8).map((_,k)=>{const i=k+16,n=metricValue(c,i),d=change(n,metricValue(c,i-1));return `<td class="heat ${d>0?'rise':'fall'}" style="--heat:${Math.min(.22,Math.abs(d)/5)}"><button data-history="${c.id}:${i}">${metricFormat(n)}</button></td>`}).join('')}<td>${state.metric==='ratio'?`${(metricValue(c,23)-metricValue(c,22)).toFixed(1)}%p`:pct(change(metricValue(c,23),metricValue(c,22)))}</td></tr>`).join('')).join('')}${!list.length?'<tr><td colspan="10" class="workbook-empty">이 구에서 현재 표본 조건에 맞는 관심 단지가 없습니다.</td></tr>':''}</tbody></table></div><p class="note" style="margin-top:12px">셀을 누르면 해당 월의 매매가·평당가·전세가·전세가율·매전갭과 원자료 구분을 볼 수 있어요. 이 표의 가격은 가상 월별 관찰가입니다.</p></section>`}
function scatter(c,rows){const all=observedRows(c,18,23,'all'),lo=Math.min(...all.map(r=>r.price))-30,hi=Math.max(...all.map(r=>r.price))+30;let svg='<svg class="scatter-chart" viewBox="0 0 720 270" role="img" aria-label="계약월별 거래 가격과 층 분포">';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3,y=220-i/3*190;svg+=`<path d="M58 ${y}H680" stroke="#e5e8eb"/><text x="48" y="${y+4}" text-anchor="end" font-size="12" fill="#6b7684">${money(v)}</text>`;}for(let m=18;m<24;m++)svg+=`<text x="${80+(m-18)/5*560}" y="250" text-anchor="middle" font-size="12" fill="#6b7684">${months[m]}</text>`;for(const r of rows){const x=80+(r.i-18)/5*560+(Number(r.date.slice(-2))-12)*1.6,y=220-(r.price-lo)/(hi-lo)*190;svg+=`<circle cx="${x}" cy="${y}" r="6" fill="${r.floor<6?'#d397b5':r.floor>20?'#1b64da':'#0f5c4a'}" opacity=".8" role="button" tabindex="0" data-trade="${r.id}" aria-label="${r.date} ${r.floor}층 ${money(r.price)}"><title>${r.date} · ${r.floor}층 · ${money(r.price)}</title></circle>`;}return `${svg}</svg><div class="chart-legend"><span><i style="background:#d397b5"></i>1~5층</span><span><i style="background:#0f5c4a"></i>6~20층</span><span><i style="background:#1b64da"></i>21층 이상</span></div>`;}
const signals=[
 {id:'lease',kind:'현장 대조',date:'11.07',candidate:'B',title:'전세 관찰가는 오르는데, 매매 광고는 늘고 있다.',lead:'가격·매물·현장 답변을 같은 단지에서 연결하면 무엇을 더 확인해야 할까요?',facts:['10월 매매·전세 관찰가를 전월 값과 대조','동일 예시 출처의 광고 수 24 → 31건','전화임장 기록: 두 광고가 같은 집일 수 있다는 답변'],hypothesis:'광고 증가 중 일부가 중복 게재라면, 서로 다른 매물의 공급 증가는 작을 수 있다.',counter:'집 식별이 완료되지 않았습니다. 광고 증가를 매도 압력 증가로 단정할 수 없어요.',next:'중개사별 광고의 동·층·향·입주일을 맞춰 묶고 확인하기',sources:[['S1','가격 관찰 원장','10.01 / 11.01 · 월별 값','관측값'],['S2','매물 스냅샷','광고 ID별 최초·최종 관찰','관측값'],['S3','전화임장 메모','11.07 · 중개사 답변 예시','전언']]},
 {id:'permit',kind:'공공 문서',date:'11.04',candidate:'E',title:'사업 발표 이후, 실제로 바뀐 단계는 무엇인가.',lead:'기사 제목에서 멈추지 않고 공고·단계·예산·일정의 변경을 추적합니다.',facts:['가상 보도자료: 주변 정비 계획 발표','가상 공고 비교: 계획 검토 단계로 기재','가상 예산 문서: 편성 항목만 확인, 집행 내역 미확인'],hypothesis:'계획 발표가 실제 사업 진전인지 확인하려면 후속 인허가와 집행 자료가 필요하다.',counter:'예산 편성은 집행 완료가 아니고, 발표된 일정도 확정 개통·입주일이 아닙니다.',next:'공식 공고의 단계 변경과 예정일 수정 여부를 다음 관측일에 확인',sources:[['P1','계획 발표','2026.09 · 가상 문서','발표'],['P2','추진 단계 기록','2026.10 · 가상 문서','검토 중'],['P3','예산 항목','집행 증빙은 미확인','미확인']]},
 {id:'mix',kind:'표본 변화',date:'11.03',candidate:'A',title:'낮아진 거래값, 저층 거래 비중 때문일까.',lead:'거래조건을 바꾸어도 같은 결론이 나오는지 확인하는 분석입니다.',facts:['같은 전용면적의 거래만 먼저 선택','최근 표본의 층 분포를 이전 기간과 대조','6~20층 필터 적용 후 건수·중위값 다시 계산'],hypothesis:'최근 중위값 변화의 일부는 저층·고층 거래 구성 변화일 수 있다.',counter:'층 조건을 맞춰도 향·동·수리 상태는 남습니다. 남은 표본이 적으면 결론을 보류합니다.',next:'상대가치 랩에서 전체 층과 6~20층 분포를 비교',sources:[['T1','실거래 예시 원표','계약일·층·면적·가격','원자료'],['T2','조건 필터 기록','동일 면적 · 해제 제외','분석 조건'],['T3','분포 비교','표본수와 중위값 동시 표시','계산']]},
 {id:'revision',kind:'늦은 신고',date:'11.05',candidate:'C',title:'지난달 거래가 없던 기간에, 새 거래가 들어왔다.',lead:'거래가 일어난 날짜와 우리가 알게 된 날짜는 다릅니다.',facts:['가상 계약일 10.28','가상 최초 관측일 11.05','11.01 발행본에는 없었던 자료'],hypothesis:'지난달의 거래 감소 해석이 늦은 반영으로 달라질 수 있다.',counter:'한 건의 추가 반영만으로 거래 회복을 결론 내릴 수 없습니다.',next:'발행 당시와 최신 반영값을 나란히 보고 정정 기록 남기기',sources:[['R1','이전 발행본','11.01 저장된 자료','보존본'],['R2','추가 관측','11.05 처음 관측','신규 반영'],['R3','계약 기록','10.28 계약 · 가상 예시','원자료']]}
];
function reportStats(c){const rows=observedRows(c,21,23,'all');if(state.asof==='latest'&&c.id==='C')rows.push({price:c.sale[23]+14});return {n:rows.length,value:median(rows.map(r=>r.price))};}
function journal(){const weekly=state.frequency==='week',c=current(),r=reportStats(universe[2]);return `${header('리서치 저널')}<div class="page"><div class="journal-header"><div><div class="eyebrow muted" style="margin-bottom:9px">03 / A research journal that remembers</div><h1 class="serif">관찰의 밀도</h1></div><button class="btn" data-action="export">${icon('download')}리포트 원문</button></div><div class="journal-layout"><aside class="archive-nav"><span class="eyebrow">RESEARCH LOG</span><button data-frequency="month" aria-pressed="${!weekly}"><span>10월 월간호</span><span>↗</span></button><button data-frequency="week" aria-pressed="${weekly}"><span>11월 1주 관측</span><span>↗</span></button></aside><article><section class="issue-main"><div><div class="row between"><span class="eyebrow">${weekly?'WEEKLY OBSERVATIONS':'MONTHLY RESEARCH'} · AI 리포트 형식 예시</span><span class="issue-number">${weekly?'W1':'10'}</span></div><h2 class="serif">${weekly?'이번 주의 새 정보,<br>이전 기록과 연결하다.':'가격의 방향보다,<br>엇갈린 지표에 주목하다.'}</h2><p class="issue-lead">${weekly?'이번 주에는 새로운 관측과 수정 사항을 모읍니다. 한 주의 적은 거래를 가격 추세로 확대하지 않고, 호가 변경·늦은 신고·공공 문서·임장 답변을 이전 기록과 대조합니다.':'월별 매매·전세 관찰가를 비교하고, 거래 표본과 매물 광고의 변화를 따로 확인합니다. 서로 다른 지표가 같은 이야기를 하는지, 어느 지점에서 어긋나는지가 이번 보고서의 질문입니다.'}<button class="source-ref" data-action="dictionary" aria-label="분석 기준과 지표 정의">1</button></p><p class="note" style="margin-top:18px">${weekly?'관측 기간 11.01—11.07':'관찰 기간 10.01—10.31 · 발행 기준 11.01'}<br>가상 자료로 만든 보고서 형식 · 실모델 생성 아님</p></div><aside class="report-callout"><span class="eyebrow">QUESTION OF THE PERIOD</span><h3 style="margin-top:14px">${c.name}</h3><p class="big" style="font-size:var(--xl)">${c.focus}</p><p>매매 관찰가 ${pct(change(c.sale[23],c.sale[22]))}<br>전세 관찰가 ${pct(change(c.rent[23],c.rent[22]))}<br>공통 관찰월 · 9월 → 10월</p><button class="btn text" style="color:inherit;justify-content:flex-start" data-evidence="${c.id}" data-kind="history">원자료로 이동 ${icon('arrow')}</button></aside></section>${journalMarketContext()}<section class="journal-section"><div class="panel-head"><h3>01. ${weekly?'이번 주 바뀐 자료':'이번 달의 교차 관측'}</h3>${pill(weekly?'새 관측 중심':'같은 월 기준','gray')}</div>${weekly?`<div class="weekly-events">${signals.map(s=>`<button class="weekly-event" data-case="${s.id}"><time>${s.date}</time><span>${pill(s.kind,'gray')}<b>${s.title}</b></span><span>↗</span></button>`).join('')}</div>`:`<div class="report-scroll"><table class="report-table"><thead><tr><th>단지</th><th>매매 변화</th><th>전세 변화</th><th>전세가율</th><th>관측 광고</th><th>근거</th></tr></thead><tbody>${universe.map(x=>`<tr><td><b>${x.name}</b><small class="muted"> · ${x.area}㎡</small></td><td>${pct(change(x.sale[23],x.sale[22]))}</td><td>${pct(change(x.rent[23],x.rent[22]))}</td><td>${(x.rent[23]/x.sale[23]*100).toFixed(1)}%</td><td>${pct(change(x.ads,x.prevAds))}</td><td><button class="source-ref" data-evidence="${x.id}" data-kind="history" aria-label="${x.name} 근거">↗</button></td></tr>`).join('')}</tbody></table></div>`}</section><section class="journal-section"><div class="panel-head wrap"><div><h3>02. 그때 알았던 것과 지금 아는 것</h3><p class="note" style="margin-top:8px">마포 파크센트럴 · 8~10월 거래 표본 · 전체 층 · 해제 제외</p></div><div class="tabs"><button data-asof="published" aria-pressed="${state.asof==='published'}">11.01 발행 당시</button><button data-asof="latest" aria-pressed="${state.asof==='latest'}">11.07 최신 반영</button></div></div><div class="revision-panel"><div><span class="note">계산에 포함한 거래</span><strong>${r.n}<small>건</small></strong></div><div><span class="note">표본 중위값</span><strong>${money(r.value)}</strong></div><p>${state.asof==='published'?'발행 시점에 확인한 자료만 사용했습니다. 이후 관측된 과거 계약은 이 발행본에 소급해서 넣지 않습니다.':'10월 28일 계약 1건이 11월 5일 처음 관측된 합성 사례를 추가했습니다. 이전 발행본은 보존하고 어떤 자료가 늘었는지 기록합니다.'}<button class="source-ref" data-action="revision" aria-label="뒤늦게 반영된 거래 기록">2</button></p></div></section><section class="journal-section report-columns"><div><h3>03. 해석과 반대 근거</h3><div class="story-item"><div class="story-tag">호가와 실거래</div><b>호가 괴리의 크기만으로 가격을 판단하지 않기</b><p>같은 평형이어도 층·향·수리 상태·입주 조건이 다릅니다. 관측 광고의 구성이 바뀌었는지 거래 원표와 함께 확인합니다.<button class="source-ref" data-evidence="B" data-kind="listings" aria-label="매물 이력 근거">3</button></p></div><div class="story-item"><div class="story-tag">공공 문서와 현장 정보</div><b>발표·전언·확정된 사실을 나누기</b><p>사업 발표와 실제 단계 진전, 예산 편성과 집행을 구분합니다. 전화임장 답변은 날짜와 전제 조건을 남기고 공식 자료와 대조합니다.<button class="source-ref" data-case="permit" aria-label="공공 문서 검토 사례">4</button></p></div></div><div><h3>04. 다음 관측으로 이어갈 질문</h3>${signals.map(s=>`<label class="task-item"><input type="checkbox" data-task="${s.id}" ${state.tasks[s.id]?'checked':''}><span>${s.next}<small>${state.tasks[s.id]?'다음 보고서에서 다시 확인하도록 표시':'단지 근거 노트와 연결된 연구 질문'}</small></span></label>`).join('')}<div class="report-notes" style="margin-top:20px"><label class="range-label" for="report-note">내 해석과 다음 질문</label><textarea id="report-note" placeholder="어떤 근거를 더 확인하면 내 판단이 달라질까요?">${esc(state.notes)}</textarea><p class="note">현재 아티팩트 안에서 유지되는 메모입니다.</p></div></div></section><div class="journal-footer"><span>관심 단지 · 관측값 · 계산 조건 · 원문 근거 · 질문</span><span>매수 시점·투자 점수·세금 계산은 이 보고서의 목적이 아닙니다.</span></div></article></div></div>${caption('03','주간·월간 저널','관측 시점과 근거를 보존하는 연구의 기억')}`;}
function shell(title,subtitle,body){return `<div class="dialog-head"><div><div class="eyebrow muted" style="margin-bottom:8px">EVIDENCE / NOT AN INVESTMENT SIGNAL</div><h2 id="dialog-title">${title}</h2><p class="note" style="margin-top:10px">${subtitle}</p></div><button class="close-button" data-action="close" aria-label="닫기">×</button></div><div class="dialog-body">${body}</div>`;}
function show(html){$('#dialog-content').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();}
function evidence(c,kind='history',month=23){let body='';if(kind==='history'){body=`<div class="evidence-grid"><section><h3>${months[month]} 월별 관찰</h3>${Object.entries(metricName).map(([k,label])=>`<div class="evidence-row"><span>${label}</span><b>${metricFormat(metricValue(c,month,k),k)}</b></div>`).join('')}</section><section class="source-item"><span class="data-badge">스크린샷의 구조를 확장한 예시</span><p>${c.region} · ${c.py}평형 / 전용 ${c.area}㎡<br>${c.year}년 · ${c.units}세대<br>${c.structure}</p><p>관찰가와 실거래는 다른 계열입니다. 평당가는 공급 ${c.py}평 기준이며 전용㎡당 가격과 혼용하지 않습니다.</p><p class="note">모든 값은 합성 예시입니다. 사용자가 보낸 시트의 실제 가격은 가져오지 않았습니다.</p></section></div>`;}
 if(kind==='trades'){const rows=observedRows(c,21,23);body=`<div class="row between wrap"><h3>계산에 사용한 거래 ${rows.length}건</h3>${pill(state.floor==='all'?'전체 층':'6~20층만','gray')}</div><p class="note" style="margin-top:10px">전용 ${c.area}㎡ · 2026.08~10 · 해제 제외 · 가격 단위 억원</p><div class="report-scroll"><table class="report-table"><thead><tr><th>계약일</th><th>층</th><th>금액</th><th>거래 유형</th><th>최초 관측일</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.date}</td><td>${r.floor}</td><td>${money(r.price)}</td><td>${r.type}</td><td>${r.observed}</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:16px">최초 관측일은 우리 시스템이 처음 본 날입니다. 실제 신고일과 동일하다고 가정하지 않습니다. 전용면적과 층을 맞춰도 다른 품질 차이는 남습니다.</p>`;}
 if(kind==='listings'){body=c.asking==null?'<div class="card"><h3>이 출처의 현재 호가는 미확인입니다.</h3><p style="margin-top:14px">확인된 과거 관찰가는 남기고 현재값은 비워 둡니다. 수집 실패와 시장에 매물이 없는 상태를 구분합니다.</p></div>':`<div class="evidence-grid"><section><h3>같은 매물을 계속 관찰하기</h3>${[['L01',c.asking,c.asking+10,'중층 · 남향','중개사 A/B 광고 묶음 후보'],['L02',c.asking+45,c.asking+45,'고층 · 남동향','입주 시점 확인 필요'],['L03',null,c.asking-15,'저층 · 남서향','광고 노출 종료 · 매매 여부 미확인']].map(([id,now,prev,cond,note])=>`<div class="source-item" style="margin:12px 0"><div class="row between"><b>${id} · ${cond}</b>${pill(now==null?'노출 종료':now!==prev?'호가 수정':'유지','gray')}</div><p>이전 ${money(prev)} → 현재 ${money(now)}</p><small class="muted">${note}</small></div>`).join('')}</section><section><h3>광고 수와 집의 수는 다릅니다</h3><div class="insight-box" style="margin-top:16px">관측 광고 ${c.prevAds} → ${c.ads}건<br>출처별 광고 ID 중복 제거와 실제 같은 집 식별은 별도입니다.</div><p style="margin-top:20px">가격 변경·재노출·노출 종료를 각각 기록합니다. 광고가 사라졌다는 이유로 거래 완료나 매도 속도를 계산하지 않습니다.</p><button class="btn" data-evidence="${c.id}" data-kind="field" style="margin-top:20px">전화·매물 임장으로 대조 ↗</button></section></div>`;}
 if(kind==='field'){body=`<div class="evidence-grid"><section><h3>전화임장 기록 · 가상 예시</h3><div class="source-item"><div class="row between"><b>11.07 · 중개사 A</b>${pill('전언','gray')}</div><p>“광고 두 개가 같은 집일 수 있고, 입주일은 조정 가능하다고 들었습니다.”</p><small class="muted">기능 예시로 작성한 문장 · 실제 상담 아님</small></div><div class="evidence-row"><span>확인할 질문</span><b>동·층·향 일치 여부</b></div><div class="evidence-row"><span>근거 대조</span><b>광고 L01 / L04</b></div></section><section><h3>매물임장 체크</h3>${[['field-light','채광·조망 직접 관찰'],['field-date','입주 가능일 서면 확인'],['field-repair','수리 상태와 추가 비용 메모'],['field-noise','출퇴근 시간대 소음 확인']].map(([id,label])=>`<label class="task-item"><input type="checkbox" data-task="${c.id}-${id}" ${state.tasks[`${c.id}-${id}`]?'checked':''}><span>${label}</span></label>`).join('')}<p class="note" style="margin-top:15px">주관적 경험·중개사 전언·문서 확인을 구분합니다. 기록은 해당 단지와 매물에 연결합니다.</p></section></div>`;}
 if(kind==='research'){body=researchInline(c)+`<button class="btn" data-evidence="${c.id}" data-kind="field" style="margin-top:20px">전화·매물 임장 기록 ↗</button>`;}
 show(shell(`${c.name} · 원자료 노트`,`단지 + 전용 ${c.area}㎡ · 날짜·조건·출처가 있는 관측 기록`,`<div class="tabs">${[['history','월별 시세'],['trades','실거래 원표'],['listings','매물 이력'],['field','전화·매물 임장'],['research','근거·질문']].map(([k,label])=>`<button data-evidence="${c.id}" data-kind="${k}" aria-pressed="${kind===k}">${label}</button>`).join('')}</div>${body}`));}
const definitions=[['월별 관찰가','동일 출처·같은 가격 기준으로 매월 기록한 값. 현재 예시는 매매·전세 관찰가이며 실거래 통계와 분리합니다.'],['거래 중위값','선택한 기간·면적·층 조건의 해제 제외 거래 가격 중앙값. 거래된 주택의 구성에 영향을 받으며 가격지수가 아닙니다.'],['3개월 변화','최근 3개월 거래 중위값 ÷ 직전 3개월 거래 중위값 − 1. 가격이 아니라 표본 구성 변화일 수도 있습니다.'],['호가 괴리','현재 관찰 호가 ÷ 최근 3개월 거래 중위값 − 1. 같은 집의 협상 할인율·고평가 점수가 아닙니다.'],['전세가율 · 매전갭','같은 월·같은 기준 전세 관찰가 ÷ 매매 관찰가. 매전갭은 매매 − 전세. 실제 보증금 인수액은 개별 계약에서 따로 확인합니다.'],['공급 평당가','매매 관찰가 ÷ 공급 평형. 전용㎡당 가격은 다른 분모이므로 두 지표를 혼용하지 않습니다.'],['가격 비율의 백분위','두 단지 가격 비율의 24개월 관측 중 현재 비율 이하의 비중. 비교군·기간을 바꾸면 달라지며 적정가 판단이 아닙니다.'],['관측 광고 변화','동일 출처에서 관찰한 광고 수의 증감. 실제 서로 다른 매물 수·시장 전체 재고·매매 완료 건수가 아닙니다.'],['거래 회전율 · 확장 지표','기간 거래 건수 ÷ 단지 세대수. 연율·집계기간·지분 거래 제외 여부를 명시한 뒤 후속 추가할 지표입니다.'],['관측 시점','계약일, 처음 관측한 날짜, 발행 기준일, 수정일을 별도 보관. 과거 보고서는 당시 이용 가능했던 정보로 재현합니다.']];
function dictionary(){show(shell('정량 지표는 정의부터','각 숫자의 분모·기간·관측 범위를 확인할 수 있어야 합니다.',`${definitions.map(([name,desc])=>`<div class="source-item" style="margin-bottom:12px"><b>${name}</b><p>${desc}</p></div>`).join('')}<p class="note"><a href="https://www.reb.or.kr/r-one/portal/stat/easyStatPage.do" target="_blank" rel="noopener noreferrer">한국부동산원 통계 유의사항</a> · <a href="https://rt.molit.go.kr/pt/xls/xls.do" target="_blank" rel="noopener noreferrer">국토부 자료 이용 안내</a></p>`));}
const services=[
 ['아실','가격과 거래량을 같은 기준으로 비교','조건 검색·지도 값 전환·두 단지/지역 비교·관심 알림·지역 통계. 월별 관측판과 비교 연구의 정보 구조로 연결합니다.','공식 지도·도움말 확인. 동적 차트·푸시 수신은 미검수.','https://asil.kr/app/sub/help.jsp?target=help4'],
 ['호갱노노','단지와 개별 매물을 계속 관찰','우리집·관심 매물의 가격 변경·생활 정보·매도 의견 비교. 단지 아래 매물 기록과 생활 조건을 따로 쌓는 구조로 연결합니다.','개발자 설명·공식 안내 확인. 본 웹은 조사 도구에서 403.','https://play.google.com/store/apps/details?hl=ko&id=com.hogangnono.hogangnono'],
 ['직방','매물 조건과 현장 확인을 구체화','상세 필터·VR/3D·중개사 문의·진단 리포트. 동·층·향·입주일·관리비와 확인 과제를 함께 기록합니다.','공식 서비스 소개·개발자 설명·공개 세대 페이지 확인. 상담 미실행.','https://company.zigbang.com/what-we-do/real-estate-service'],
 ['디스코','주소에 거래와 공적 자료를 연결','유사거래·지도 레이어·토지/건물 자료·여러 관심 목록. 비교 근거와 공공 문서를 단지·주소에 연결합니다.','공식 웹 공개 HTML 확인. 로그인·유료 열람 결과는 미검수.','https://www.disco.re/'],
 ['네이버 부동산','관심 매물과 조건별 새 관측','단지/매물 관심 분리·필터·새 매물 알림·확인 방식. 사라진 광고도 이전 기록을 보존하고 거래 여부는 따로 확인합니다.','공식 도움말 확인. 외부 매물 API 이용권한은 미확인.','https://help.pay.naver.com/faq/content.help?faqId=17126'],
 ['KB부동산','서로 다른 가격 계열을 분리','시세·실거래·매물가격·우리집·변동 알림. 관찰가·평가 시세·실거래를 섞지 않고 출처별로 비교합니다.','공식 개발자 설명 확인. 2023년 데이터허브 가이드는 과거 자료로 구분.','https://play.google.com/store/apps/details?hl=ko&id=com.kbstar.land']
];
function research(tab=state.researchTab){state.researchTab=tab;let body='';if(tab==='services')body=`<p class="note" style="margin-bottom:20px">2026.11.07 조사 · 6개 서비스의 공식 기능 40개를 조사했습니다. 아래는 서비스별로 가져올 방향과 실제 확인한 범위입니다.</p><div class="research-overview">${services.map(([name,focus,desc,limit,url])=>`<article class="card research-feature"><h3>${name}</h3><p style="margin:12px 0"><b>${focus}</b></p><p>${desc}</p><p class="note" style="margin-top:12px">${limit}</p><a href="${url}" target="_blank" rel="noopener noreferrer" style="display:inline-block;margin-top:14px">공식 출처 ↗</a></article>`).join('')}</div>`;
 if(tab==='design')body=`<div class="stack-lg"><div class="insight-box"><b>관심 부동산을 주식의 퀀트처럼 꾸준히 연구한다.</b><br>주간에는 새 관측과 변경, 월간에는 가격·거래·전세·매물의 교차 흐름을 살핍니다. 가격 판단은 사용자가 하고 자금·세금은 그 뒤 상세 검토로 연결합니다.</div>${[['01 퀀트 워크북','월별 매매·전세·평당가·전세가율·매전갭과 고정 단지 정보를 묶습니다. 정량 관측표와 원자료를 오갑니다.'],['02 여러 단지 비교','체크한 모든 단지를 차트와 비교표에 함께 놓습니다. 매매·전세·전세가율·매전갭, 기준월/기준 단지 100과 상세 거래·근거를 연결합니다.'],['01 서울 매물 흐름','서울 전역·25개 자치구의 매매/전세 광고를 일별로 축적하고 같은 범위에서 증감을 비교합니다. 수집 누락은 집계 보류로 구분합니다.'],['03 주간·월간 저널','그때 알 수 있었던 자료를 보존하고, 최신 정정과 비교합니다. 지난 질문과 내 해석을 다음 관측으로 이어갑니다.']].map(([title,desc])=>`<div class="source-item"><h3>${title}</h3><p>${desc}</p></div>`).join('')}<div class="source-item"><b>원천과 기록부터 고도화</b><p>공공 실거래·전월세 원천, 출처가 있는 호가 관찰, 매물 식별과 변경 이력, 발표일·관측일이 있는 공공 사건, 현장 기록을 축적합니다. 민간 사이트의 공개 화면은 외부 API·수집·재배포 허가를 뜻하지 않습니다.</p></div></div>`;
 show(shell('공식 리서치와 컨셉 설계','기능을 나열하기보다 지속적인 부동산 연구의 흐름으로 재구성했습니다.',`<div class="tabs"><button data-research="services" aria-pressed="${tab==='services'}">서비스별 발견</button><button data-research="design" aria-pressed="${tab==='design'}">제품의 큰 그림</button></div>${body}`));}
function revision(){show(shell('계약일과 관측일 사이','과거를 그때 알고 있었던 정보로 재현하는 예시입니다.',`<div class="source-chain"><div class="source-item"><b>10.28 계약</b><p>계약 발생일<br>가상 거래 ${money(universe[2].sale[23]+14)}</p></div><div class="source-item"><b>11.01 발행</b><p>아직 이 거래를 관측하지 못함<br>기존 발행본 보존</p></div><div class="source-item"><b>11.05 첫 관측</b><p>지난 계약월에 새 자료가 추가됨<br>다음 발행본의 정정으로 기록</p></div></div><p class="note" style="margin-top:20px">실제 국토부 공개자료에는 신고 시차·정정·해제가 있습니다. 이 사례의 거래와 날짜는 합성입니다. 최초 관측일을 실제 신고일로 가정하지 않습니다. <a href="https://rt.molit.go.kr/pt/xls/xls.do" target="_blank" rel="noopener noreferrer">국토부 안내 ↗</a></p>`));}
function tradeDetail(id){const c=universe.find(x=>x.rows.some(r=>r.id===id)),r=c?.rows.find(x=>x.id===id);if(!r)return;show(shell(`${c.name} · 거래 한 건의 근거`,'그래프의 점과 계산 원표가 같은 기록을 가리킵니다.',`<div class="card">${[['계약일',r.date],['최초 관측일',r.observed],['전용면적',`${r.area}㎡`],['층',`${r.floor}층`],['거래금액',money(r.price)],['거래유형',r.type],['해제 상태',r.cancelled?'해제':'해제 기록 없음'],['자료 종류','합성 거래 예시']].map(([k,v])=>`<div class="evidence-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div>`));}
function reportText(){return `둘이서은퇴 부동산 리서치 · ${state.frequency==='week'?'2026년 11월 1주':'2026년 10월'}\n합성 자료 기반 인터랙티브 컨셉 / 실제 시장·AI 생성 아님\n\n${journalMarketText()}\n\n${universe.map(c=>`${c.name} · 전용 ${c.area}㎡\n매매 ${money(c.sale[23])} / 전세 ${money(c.rent[23])}\n전월 매매 변화 ${pct(change(c.sale[23],c.sale[22]))} / 전세 변화 ${pct(change(c.rent[23],c.rent[22]))}\n전세가율 ${(c.rent[23]/c.sale[23]*100).toFixed(1)}% / 매전갭 ${money(c.sale[23]-c.rent[23])}\n관측 광고 변화 ${pct(change(c.ads,c.prevAds))}\n연구 질문: ${c.focus}`).join('\n\n')}\n\n발행 시점: ${state.asof==='published'?'11.01 당시 자료':'11.07까지 반영한 정정 예시'}\n\n다음 관측 질문\n${signals.filter(s=>state.tasks[s.id]).map(s=>s.next).join('\n')||'선택한 질문 없음'}\n\n나의 해석\n${state.notes||'기록 전'}\n\n원자료는 이 아티팩트의 합성 관찰값입니다. 지표 정의·표본 조건·관측일을 보존하며 매수 판단이나 가격 예측을 제공하지 않습니다.`;}
function exportReport(){show(shell('리서치 기록 가져가기','내 해석과 다시 확인할 질문을 포함한 예시 리포트입니다.',`<textarea id="report-export" readonly style="width:100%;height:350px;border:1px solid var(--line);padding:16px;font:inherit;line-height:1.8">${esc(reportText())}</textarea><button class="btn primary" data-action="download" style="margin-top:20px">${icon('download')}텍스트 내려받기</button><p class="note" style="margin-top:12px">뷰어가 다운로드를 제한하면 위 텍스트를 선택해 복사할 수 있습니다.</p>`));}
function render(){const app=$('#app');app.className=`stage ${state.view==='workbook'?'observatory':state.view==='relative'?'atlas':state.view==='market'?'market':'journal'}`;app.dataset.view=state.view;app.innerHTML=({workbook,relative,market,journal}[state.view])();syncGroupChecks();applyResearchLayout();document.querySelectorAll('.concept-nav button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view||b.dataset.view==='market'&&state.view==='workbook')));}
function select(id){state.selected=id;}
function setView(v){if(!['workbook','relative','market','journal'].includes(v))return;$('#detail').close();state.view=v;render();}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-trade],[data-inventory-day]');if(!b)return;
 if(b.dataset.watchDistrict){state.watchDistrict=b.dataset.watchDistrict;const local=visibleComplexes();if(state.view==='workbook'&&local.length&&!local.some(c=>c.id===state.selected))select(local[0].id);render();document.querySelector(`[data-watch-district="${state.watchDistrict}"]`)?.focus();return;}
 if(b.dataset.compareRemove){state.compare=state.compare.filter(id=>id!==b.dataset.compareRemove);normalizeComparison();render();return;}
 if(b.dataset.invKind){state.invKind=b.dataset.invKind;render();return;}
 if(b.dataset.invPeriod){state.invPeriod=Number(b.dataset.invPeriod);render();return;}
 if(b.dataset.invScale){state.invScale=b.dataset.invScale;render();return;}
 if(b.dataset.district){state.invDistrict=b.dataset.district;render();return;}
 if(b.dataset.inventoryDay){inventoryEvidence(Number(b.dataset.inventoryDay));return;}
 if(b.dataset.districtCandidate){select(b.dataset.districtCandidate);state.watchDistrict=districtOf[b.dataset.districtCandidate];setView('workbook');return;}
 if(b.dataset.compareMetric){state.compareMetric=b.dataset.compareMetric;render();return;}
 if(b.dataset.detail){select(b.dataset.detail);render();return;}
 if(b.dataset.view){setView(b.dataset.view);return;}
 if(b.dataset.open){setView(b.dataset.open);return;}
 if(b.dataset.select){select(b.dataset.select);render();return;}
 if(b.dataset.mode){state.mode=b.dataset.mode;render();return;}
 if(b.dataset.metric){state.metric=b.dataset.metric;render();return;}
 if(b.dataset.chart){state.chart=b.dataset.chart;render();return;}
 if(b.dataset.period){state.period=Number(b.dataset.period);render();return;}
 if(b.dataset.floor){state.floor=b.dataset.floor;render();return;}
 if(b.dataset.frequency){state.frequency=b.dataset.frequency;render();return;}
 if(b.dataset.asof){state.asof=b.dataset.asof;render();return;}
 if(b.dataset.case){researchNote(b.dataset.case);return;}
 if(b.dataset.research){research(b.dataset.research);return;}
 if(b.dataset.history){const [id,m]=b.dataset.history.split(':');evidence(universe.find(x=>x.id===id),'history',Number(m));return;}
 if(b.dataset.evidence){evidence(universe.find(x=>x.id===b.dataset.evidence),b.dataset.kind);return;}
 if(b.dataset.trade){tradeDetail(b.dataset.trade);return;}
 if(b.dataset.signalSource!==undefined){const s=signals.find(x=>x.id===state.case),ref=s.sources[Number(b.dataset.signalSource)];show(shell(`${ref[0]} · ${ref[1]}`,'실제 문서가 아닌, 근거 연결 구조를 보여주는 가상 기록입니다.',`<div class="source-item"><span class="data-badge">${ref[3]}</span><p>${ref[2]}</p><p>${s.facts[Number(b.dataset.signalSource)]}</p><p class="note">실제 구현에서는 원문 URL·발표일·관측일·변경본·관련 단지 ID를 보관합니다.</p></div>`));return;}
 const a=b.dataset.action;if(a==='collection')collection();if(a==='compare-all'){state.compare=universe.map(c=>c.id);render();}if(a==='compare-clear'){state.compare=[];render();}if(a==='close')$('#detail').close();if(a==='dictionary')dictionary();if(a==='research')research();if(a==='revision')revision();if(a==='export')exportReport();
 if(a==='download'){const blob=new Blob([reportText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='부동산-리서치-가상예시.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-inventory-day]')){e.preventDefault();inventoryEvidence(Number(e.target.dataset.inventoryDay));}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-trade]')){e.preventDefault();tradeDetail(e.target.dataset.trade);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='market-district-select'){state.invDistrict=el.value;render();$('#market-district-select').focus();}if(el.dataset.compareGroup){const ids=el.dataset.groupIds.split(',');state.compare=el.checked?[...new Set([...state.compare,...ids])]:state.compare.filter(id=>!ids.includes(id));const focusId=el.id;normalizeComparison();render();document.getElementById(focusId)?.focus();}if(el.id==='sample-filter'){state.minSamples=Number(el.value);render();$('#sample-filter').focus();}if(el.id==='factor-sort'){state.sort=el.value;render();$('#factor-sort').focus();}if(el.id==='benchmark-select'){state.benchmark=el.value;render();$('#benchmark-select').focus();}if(el.id==='inventory-asof'){state.invDay=Number(el.value);render();$('#inventory-asof').focus();}if(el.dataset.compare){if(el.checked&&!state.compare.includes(el.dataset.compare))state.compare.push(el.dataset.compare);if(!el.checked)state.compare=state.compare.filter(id=>id!==el.dataset.compare);const focusId=el.id;normalizeComparison();render();document.getElementById(focusId)?.focus();}if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;if(state.view==='journal'&&!$('#detail').open)render();}});
document.addEventListener('input',e=>{if(e.target.id==='report-note')state.notes=e.target.value;});
$('#detail').addEventListener('close',()=>{if(state.view==='journal')render();document.querySelector(`.concept-nav [data-view="${state.view==='workbook'?'market':state.view}"]`)?.focus();});
